#!/usr/bin/env python3
# -*- coding: utf-8 -*-
'''SQLI-001 本地HTTP验证草案（最小化、只读）。

对目标参数做“正常输入 vs 最小标记输入”的响应对照，用于确认 id 是否进入
WHERE id=... 的字符串拼接位置。仅限授权靶场使用。
不枚举数据库、不读取额外敏感数据、不批量修改记录。
'''
import argparse
import difflib
import os
import re
import sys
import urllib.error
import urllib.parse
import urllib.request

SQL_ERROR_PATTERNS = [
    'SQL syntax',
    'Warning: mysql_',
    'check the manual that corresponds to your MySQL server version',
    'quoted string not properly terminated',
]
AUTH_HINTS = ['login', 'signin', 'auth']
PHP_FATAL_PATTERNS = ['Fatal error', 'Parse error', 'Call to undefined function']
NORMAL_BRANCH_HINT = 'Your Login name'
NO_PARAM_HINT = 'Please input the ID'


def load_cookie(session_file):
    if not session_file:
        return None
    cookies = []
    with open(session_file, 'r', encoding='utf-8') as fh:
        for raw in fh:
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            if line.lower().startswith('cookie:'):
                line = line.split(':', 1)[1].strip()
            cookies.append(line)
    joined = '; '.join(part for part in cookies if part)
    return joined or None


def build_url(base_url, path, param, value):
    url = base_url.rstrip('/') + path
    sep = '&' if '?' in url else '?'
    return '{}{}{}={}'.format(url, sep, urllib.parse.quote(param), urllib.parse.quote(value, safe=''))


def fetch(url, cookie, timeout):
    req = urllib.request.Request(url, method='GET')
    req.add_header('User-Agent', 'sqli-001-lab-verifier/1.0')
    req.add_header('Accept', 'text/html,application/xhtml+xml')
    if cookie:
        req.add_header('Cookie', cookie)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, dict(resp.headers), resp.read(65536).decode('utf-8', 'replace'), None
    except urllib.error.HTTPError as exc:
        return exc.code, dict(exc.headers or {}), exc.read(65536).decode('utf-8', 'replace'), None
    except Exception as exc:
        return None, {}, '', '{}: {}'.format(type(exc).__name__, exc)


def classify(status, headers, body, transport_error):
    notes = []
    if transport_error:
        return 'TRANSPORT_ERROR', ['请求未完成: ' + transport_error]
    if status is not None and status in (301, 302, 303, 307, 308):
        notes.append('HTTP {} 跳转, Location={}'.format(status, headers.get('Location')))
    location = headers.get('Location') or ''
    for hint in AUTH_HINTS:
        if location and hint in location.lower():
            notes.append('疑似认证跳转, Location 含 ' + hint)
    for pat in PHP_FATAL_PATTERNS:
        if re.search(pat, body, re.I):
            notes.append('疑似 PHP 接口不兼容: ' + pat)
    for pat in SQL_ERROR_PATTERNS:
        if re.search(pat, body, re.I):
            notes.append('疑似 SQL 语法错误回显: ' + pat)
    if NORMAL_BRANCH_HINT in body:
        notes.append('命中正常回显分支: ' + NORMAL_BRANCH_HINT)
    if NO_PARAM_HINT in body:
        notes.append('命中缺参提示分支: ' + NO_PARAM_HINT)
    if any(re.search(p, body, re.I) for p in SQL_ERROR_PATTERNS):
        marker = 'SQL_ERROR_SUSPECT'
    elif notes:
        marker = 'REVIEW'
    else:
        marker = 'PLAIN'
    return marker, notes


def main():
    parser = argparse.ArgumentParser(description='SQLI-001 本地HTTP验证草案, 最小化只读')
    parser.add_argument('--base-url', required=True, help='靶场基址, 例如 http://127.0.0.1:8080')
    parser.add_argument('--path', required=True, help='目标脚本路径, 例如 /sqli/Less-1/')
    parser.add_argument('--param', default='id', help="查询参数名, 来自代码 $_GET['id']")
    parser.add_argument('--session-file', default=None, help='可选, Cookie 文本文件')
    parser.add_argument('--baseline-value', default='1', help='正常输入, 用于确认业务路径可达')
    parser.add_argument('--probe-value', default="1'", help='最小标记输入, 单个闭引号')
    parser.add_argument('--timeout', type=float, default=10.0)
    parser.add_argument('--dump-dir', default=None, help='可选, 保存原始响应的目录')
    args = parser.parse_args()

    try:
        cookie = load_cookie(args.session_file)
    except OSError as exc:
        print('会话文件读取失败: {}'.format(exc), file=sys.stderr)
        return 3

    results = {}
    for label, value in (('BASELINE', args.baseline_value), ('PROBE', args.probe_value)):
        url = build_url(args.base_url, args.path, args.param, value)
        status, headers, body, err = fetch(url, cookie, args.timeout)
        marker, notes = classify(status, headers, body, err)
        results[label] = {'status': status, 'body': body, 'marker': marker, 'notes': notes}
        print('[{}] {} -> HTTP {} / {}'.format(label, url, status, marker))
        for note in notes:
            print('    - ' + note)
        if args.dump_dir:
            os.makedirs(args.dump_dir, exist_ok=True)
            with open(os.path.join(args.dump_dir, label.lower() + '.html'), 'w', encoding='utf-8') as fh:
                fh.write(body)

    print('')
    print('--- 响应体差异摘要 (最多 40 行, 人工复核用) ---')
    diff = difflib.unified_diff(
        results['BASELINE']['body'].splitlines(),
        results['PROBE']['body'].splitlines(),
        fromfile='baseline', tofile='probe', lineterm='', n=1,
    )
    for line in list(diff)[:40]:
        print(line)

    print('')
    reachable = results['BASELINE']['status'] == 200 and results['BASELINE']['marker'] in ('PLAIN', 'REVIEW')
    sql_error = results['PROBE']['marker'] == 'SQL_ERROR_SUSPECT'
    print('判定提示:')
    print('  正常输入业务路径可达: {}'.format(reachable))
    print('  标记输入出现 SQL 报错特征: {}'.format(sql_error))
    print('  若两者同时为真, 支持 id 进入 WHERE id=... 的拼接位置;')
    print('  若正常输入被 302 跳到登录页, 先补 --session-file, 不要把跳转当成注入证据;')
    print('  若出现 Fatal error 或空响应, 先排除 PHP 版本/接口不兼容再复测。')
    return 0 if reachable else 2


if __name__ == '__main__':
    raise SystemExit(main())
